CREATE proc [dbo].[UpdateAfterKOT] @order_key as nvarchar(50) as Declare @IsExist as nvarchar(20); select @IsExist = table_no from tempdine_in_order where order_key =@order_key delete from tempdine_in_order where order_key = @order_key update Tables set table_status= 'Close' where tables = @IsExist delete e from Order_Detail_ExtraItem e inner join order_detail d on d.id  = e.Order_Detail_Id where d.order_key =@order_key delete from Order_Detail where order_key =@order_key delete from OrderKOT where orderkey =@order_key delete from DealsOnSpotItems where order_key =@order_key delete from customerPOS where order_key = @order_key delete from [2StepWok_Items] where order_key =@order_key delete from [2StepWok_Items_Temp] where order_key =@order_key delete from [3StepWok_Items] where order_key = @order_key delete from [3StepWok_Items_Temp] where order_key =@order_key delete from Step_Deal_Items where order_key =@order_key delete from Step_Deal_Items_Temp where order_key =@order_key Delete from Deals_item  where order_key = @order_key